import '../widgets/cat_card.dart';

/// Grid of cat cards backed by the [CollectionBloc].
///
/// Creates its own bloc and starts loading right away; the repository can be
/// injected for tests.
class CollectionPage extends StatelessWidget {
  const CollectionPage({super.key, this.repository});

  /// Repository used to fetch the cats; defaults to the fake one.
  final CatsRepository? repository;

  @override
  Widget build(BuildContext context) {
    return BlocProvider(
      create: (_) =>
          CollectionBloc(repository: repository ?? const FakeCatsRepository())
            ..add(const CollectionStarted()),
      child: const _CollectionView(),
    );
  }
}

class _CollectionView extends StatelessWidget {
  const _CollectionView();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Collection')),
      body: BlocBuilder<CollectionBloc, CollectionState>(
        builder: (context, state) => switch (state) {
          CollectionLoadSuccess(:final cats) => GridView.builder(
            padding: const EdgeInsets.all(8),
            gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
              maxCrossAxisExtent: 200,
              mainAxisSpacing: 8,
              crossAxisSpacing: 8,
              childAspectRatio: 0.75,
            ),
            itemCount: cats.length,
            itemBuilder: (context, index) => CatCard(cat: cats[index]),
          ),
          CollectionLoadFailure() => const _CollectionError(),
          CollectionInitial() || CollectionLoadInProgress() => const Center(
            child: CircularProgressIndicator(),
          ),
        },
      ),
    );
  }
}

class _CollectionError extends StatelessWidget {
  const _CollectionError();

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(
            Icons.error_outline,
            size: 48,
            color: Theme.of(context).colorScheme.error,
          ),
          const SizedBox(height: 8),
          const Text('Failed to load cats'),
        ],
      ),
    );
  }
}
import 'package:flutter/material.dart';
import 'package:repositories/repositories.dart';

import 'star_rating.dart';

/// Card of the collection grid showing a cat's image, name and rating.
class CatCard extends StatelessWidget {
  const CatCard({super.key, required this.cat});

  /// The cat displayed by this card.
  final Cat cat;

  @override
  Widget build(BuildContext context) {
    return Card(
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Expanded(child: Image.asset(cat.imageUrl, fit: BoxFit.cover)),
          Padding(
            padding: const EdgeInsets.all(8),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  cat.name,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: Theme.of(context).textTheme.titleMedium,
                ),
                const SizedBox(height: 4),
                StarRating(rating: cat.rating),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
import 'package:flutter/material.dart';

/// Row of [total] stars with exactly [rating] of them filled.
class StarRating extends StatelessWidget {
  const StarRating({super.key, required this.rating, this.total = 5});

  /// Number of filled stars, from 1 to [total].
  final int rating;

  /// Total number of stars in the row.
  final int total;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        for (var i = 1; i <= total; i++)
          Icon(
            i <= rating ? Icons.star : Icons.star_border,
            size: 16,
            color: Colors.amber,
          ),
      ],
    );
  }
}

