import 'home_page.dart';
import 'profile_page.dart';

/// The destinations offered by the [ShellPage], in display order.
enum ShellDestination { home, explore, collection, profile }

/// Top-level container hosting the four main destinations.
///
/// The destination is switched through a [NavigationBar] and kept in an
/// [IndexedStack], so the state of every destination survives tab changes.
class ShellPage extends StatefulWidget {
  const ShellPage({super.key});

  @override
  State<ShellPage> createState() => _ShellPageState();
}

class _ShellPageState extends State<ShellPage> {
  ShellDestination _destination = ShellDestination.home;

  static const Map<ShellDestination, Widget> _pages = {
    ShellDestination.home: HomePage(),
    ShellDestination.explore: ExplorePage(),
    ShellDestination.collection: CollectionPage(),
    ShellDestination.profile: ProfilePage(),
  };

  static const Map<ShellDestination, (IconData, IconData)> _icons = {
    ShellDestination.home: (Icons.home_outlined, Icons.home),
    ShellDestination.explore: (Icons.explore_outlined, Icons.explore),
    ShellDestination.collection: (
      Icons.collections_bookmark_outlined,
      Icons.collections_bookmark,
    ),
    ShellDestination.profile: (Icons.person_outline, Icons.person),
  };

  void _onDestinationSelected(int index) {
    setState(() => _destination = ShellDestination.values[index]);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: IndexedStack(
        index: _destination.index,
        children: _pages.values.toList(growable: false),
      ),
      bottomNavigationBar: NavigationBar(
        selectedIndex: _destination.index,
        onDestinationSelected: _onDestinationSelected,
        destinations: [
          for (final destination in ShellDestination.values)
            NavigationDestination(
              icon: Icon(_icons[destination]!.$1),
              selectedIcon: Icon(_icons[destination]!.$2),
              label: destination.name.capitalize,
            ),
        ],
      ),
    );
  }
}

extension on String {
  String get capitalize =>
      isEmpty ? this : '${this[0].toUpperCase()}${substring(1)}';
}
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:dark_cats_factory/pages/collection_page.dart';
import 'package:dark_cats_factory/pages/explore_page.dart';
import 'package:dark_cats_factory/pages/home_page.dart';
import 'package:dark_cats_factory/pages/profile_page.dart';
import 'package:dark_cats_factory/pages/shell_page.dart';

void main() {
  Future<void> pumpShell(WidgetTester tester) async {
    await tester.pumpWidget(const MaterialApp(home: ShellPage()));
    await tester.pumpAndSettle();
  }

  Future<void> tapDestination(WidgetTester tester, String label) async {
    await tester.tap(find.text(label).last);
    await tester.pumpAndSettle();
  }

  testWidgets('shell offers the four destinations', (tester) async {
    await pumpShell(tester);

    final navigationBar = find.byType(NavigationBar);
    expect(navigationBar, findsOneWidget);
    expect(
      find.descendant(of: navigationBar, matching: find.text('Home')),
      findsOneWidget,
    );
    expect(
      find.descendant(of: navigationBar, matching: find.text('Explore')),
      findsOneWidget,
    );
    expect(
      find.descendant(of: navigationBar, matching: find.text('Collection')),
      findsOneWidget,
    );
    expect(
      find.descendant(of: navigationBar, matching: find.text('Profile')),
      findsOneWidget,
    );
  });

  testWidgets('home is the initial destination', (tester) async {
    await pumpShell(tester);

    expect(find.byType(HomePage), findsOneWidget);
    expect(find.byType(ExplorePage), findsNothing);
    expect(find.byType(CollectionPage), findsNothing);
