/// Blocs (state management) for the application pages.
library;

export 'src/collection/collection_bloc.dart';
export 'src/collection/collection_event.dart';
export 'src/collection/collection_state.dart';
import 'package:equatable/equatable.dart';
import 'package:repositories/repositories.dart';

/// Base class of all collection states.
sealed class CollectionState extends Equatable {
  const CollectionState();

  @override
  List<Object?> get props => const [];
}

/// Nothing has been requested yet.
final class CollectionInitial extends CollectionState {
  const CollectionInitial();
}

/// The collection is being fetched.
final class CollectionLoadInProgress extends CollectionState {
  const CollectionLoadInProgress();
}

/// The collection has been fetched successfully.
final class CollectionLoadSuccess extends CollectionState {
  const CollectionLoadSuccess(this.cats);

  /// The fetched cats, in display order.
  final List<Cat> cats;

  @override
  List<Object?> get props => [cats];
}

/// Fetching the collection failed.
final class CollectionLoadFailure extends CollectionState {
  const CollectionLoadFailure(this.error);

  /// The error that caused the failure.
  final Object error;

  @override
  List<Object?> get props => [error];
}
import 'package:equatable/equatable.dart';

/// Base class of all collection events.
sealed class CollectionEvent extends Equatable {
  const CollectionEvent();

  @override
  List<Object?> get props => const [];
}

/// Signals that the collection should be loaded.
final class CollectionStarted extends CollectionEvent {
  const CollectionStarted();
}
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:repositories/repositories.dart';

import 'collection_event.dart';
import 'collection_state.dart';

/// Loads and exposes the collection of cats.
final class CollectionBloc extends Bloc<CollectionEvent, CollectionState> {
  /// Creates a bloc that fetches cats through [repository].
  CollectionBloc({required this._repository})
    : super(const CollectionInitial()) {
    on<CollectionStarted>(_onStarted);
  }

  final CatsRepository _repository;

  Future<void> _onStarted(
    CollectionStarted event,
    Emitter<CollectionState> emit,
  ) async {
    emit(const CollectionLoadInProgress());
    try {
      emit(CollectionLoadSuccess(await _repository.fetchCats()));
    } on Object catch (error) {
      emit(CollectionLoadFailure(error));
    }
  }
}

