/// Card of the collection grid showing a cat's image, name and rating.
class CatCard extends StatelessWidget {
  const CatCard({super.key, required this.cat});

  /// The cat displayed by this card.
  final Cat cat;

  @override
  Widget build(BuildContext context) {
    return Card(
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Expanded(child: Image.asset(cat.imageUrl, fit: BoxFit.cover)),
          Padding(
            padding: const EdgeInsets.all(8),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  cat.name,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: Theme.of(context).textTheme.titleMedium,
                ),
                const SizedBox(height: 4),
                StarRating(rating: cat.rating),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
import 'package:flutter/material.dart';

/// Row of [total] stars with exactly [rating] of them filled.
class StarRating extends StatelessWidget {
  const StarRating({super.key, required this.rating, this.total = 5});

  /// Number of filled stars, from 1 to [total].
  final int rating;

  /// Total number of stars in the row.
  final int total;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        for (var i = 1; i <= total; i++)
          Icon(
            i <= rating ? Icons.star : Icons.star_border,
            size: 16,
            color: Colors.amber,
          ),
      ],
    );
  }
}

