import 'dart:async';

import 'package:dark_cats_factory/pages/collection_page.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:repositories/repositories.dart';

/// Waits until [provider] delivers a decoded image.
///
/// The image codec runs on the real event loop, which fake async cannot
/// drive, so this must be called inside [WidgetTester.runAsync]. Waiting
/// also warms the image cache, so later [Image]s paint without a race.
Future<void> _waitForImage(ImageProvider provider) {
  final completer = Completer<void>();
  provider
      .resolve(const ImageConfiguration())
      .addListener(
        ImageStreamListener(
          (_, _) => completer.complete(),
          onError: (Object error, StackTrace? stackTrace) =>
              completer.completeError(error, stackTrace),
        ),
      );
  return completer.future;
}

void main() {
  testWidgets('collection page matches the golden', (tester) async {
    tester.view.devicePixelRatio = 1.0;
    tester.view.physicalSize = const Size(390, 844);
    addTearDown(tester.view.reset);

    await tester.pumpWidget(const MaterialApp(home: CollectionPage()));

    // Decode every fake cat picture before settling, so the grid is painted
    // with the loaded images instead of racing the golden capture.
    await tester.runAsync(() async {
      final cats = await const FakeCatsRepository().fetchCats();
      await Future.wait([
        for (final cat in cats) _waitForImage(AssetImage(cat.imageUrl)),
      ]);
    });

    await tester.pumpAndSettle();

    await expectLater(
      find.byType(CollectionPage),
      matchesGoldenFile('goldens/collection_page.png'),
    );
  });
}
import 'dart:async';

import 'package:dark_cats_factory/pages/collection_page.dart';
import 'package:dark_cats_factory/widgets/cat_card.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:repositories/repositories.dart';

class _StubCatsRepository implements CatsRepository {
  final Completer<List<Cat>> _completer = Completer<List<Cat>>();

  void succeedWith(List<Cat> cats) => _completer.complete(cats);

  void failWith(Object error) => _completer.completeError(error);

  @override
  Future<List<Cat>> fetchCats() => _completer.future;
}

const _cats = [
  Cat(id: 'onyx', name: 'Onyx', imageUrl: 'assets/cats/onyx.png', rating: 5),
  Cat(id: 'salem', name: 'Salem', imageUrl: 'assets/cats/salem.png', rating: 1),
  Cat(id: 'luna', name: 'Luna', imageUrl: 'assets/cats/luna.png', rating: 2),
];

Finder _cardOf(String name) =>
    find.ancestor(of: find.text(name), matching: find.byType(CatCard));

void main() {
  Future<void> pumpCollection(
    WidgetTester tester,
    _StubCatsRepository repo,
  ) async {
    await tester.pumpWidget(
      MaterialApp(home: CollectionPage(repository: repo)),
    );
    await tester.pump();
  }

  testWidgets('shows a progress indicator while cats are loading', (
    tester,
  ) async {
    final repository = _StubCatsRepository();
    await pumpCollection(tester, repository);

    expect(find.byType(CircularProgressIndicator), findsOneWidget);
    expect(find.byType(CatCard), findsNothing);
  });

  testWidgets('renders a card for every fetched cat', (tester) async {
    final repository = _StubCatsRepository();
    await pumpCollection(tester, repository);

    repository.succeedWith(_cats);
    await tester.pumpAndSettle();

    expect(find.byType(CatCard), findsNWidgets(_cats.length));
    for (final cat in _cats) {
      expect(find.text(cat.name), findsOneWidget);
    }
    expect(find.byType(CircularProgressIndicator), findsNothing);
  });

  testWidgets('renders every card with the cat image', (tester) async {
    final repository = _StubCatsRepository();
    await pumpCollection(tester, repository);

    repository.succeedWith(_cats);
    await tester.pumpAndSettle();

    for (final cat in _cats) {
      final image = find.descendant(
        of: _cardOf(cat.name),
        matching: find.byWidgetPredicate(
          (widget) =>
              widget is Image &&
              widget.image is AssetImage &&
              (widget.image as AssetImage).assetName == cat.imageUrl,
